// Parse action and parameters
const action = $json.body?.action || $json.action || 'get';
const conversationId = $json.body?.conversationId || $json.conversationId || '';
const userMessage = $json.body?.userMessage || $json.userMessage || '';
const botResponse = $json.body?.botResponse || $json.botResponse || '';
const intent = $json.body?.intent || $json.intent || '';

return {
  json: {
    action,
    conversationId,
    userMessage,
    botResponse,
    intent,
    timestamp: new Date().toISOString()
  }
};

// Parse Redis response or create new conversation
const conversationId = $node['Parse Action'].json.conversationId;
let context = null;

try {
  // Redis node returns value directly
  const redisData = $json.value || $json || null;
  if (redisData && redisData !== null) {
    context = typeof redisData === 'string' ? JSON.parse(redisData) : redisData;
  }
} catch (e) {
  // Redis failed or no data
}

if (!context) {
  // Create new conversation
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  context = {
    conversation_id: conversationId,
    created_at: now.toISOString(),
    last_message_at: now.toISOString(),
    expires_at: expiresAt.toISOString(),
    messages: [],
    context_summary: ''
  };
}

return { json: { context } };

// Load existing context and add new messages
const inputData = $node['Parse Action'].json;
const conversationId = inputData.conversationId;

let context = null;

try {
  // Redis node returns value directly
  const redisData = $json.value || $json || null;
  if (redisData && redisData !== null) {
    context = typeof redisData === 'string' ? JSON.parse(redisData) : redisData;
  }
} catch (e) {
  // Redis failed or no data
}

if (!context) {
  // Create new conversation
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  context = {
    conversation_id: conversationId,
    created_at: now.toISOString(),
    last_message_at: now.toISOString(),
    expires_at: expiresAt.toISOString(),
    messages: [],
    context_summary: ''
  };
}

// Add user message
if (inputData.userMessage) {
  context.messages.push({
    message_id: `msg-${Date.now()}-user`,
    sender: 'user',
    content: inputData.userMessage,
    timestamp: inputData.timestamp,
    message_type: 'question'
  });
}

// Add bot response
if (inputData.botResponse) {
  context.messages.push({
    message_id: `msg-${Date.now()}-bot`,
    sender: 'bot',
    content: inputData.botResponse,
    timestamp: new Date().toISOString(),
    message_type: 'answer'
  });
}

// Update metadata
context.last_message_at = new Date().toISOString();

// Prune old messages (keep last 10 for context)
if (context.messages.length > 10) {
  context.messages = context.messages.slice(-10);
}

// Update context summary (last 5 messages)
const recentMessages = context.messages.slice(-5);
context.context_summary = recentMessages.map(m => `${m.sender}: ${m.content.substring(0, 100)}`).join('\n');

// Check for similar queries (FR-015a)
const currentQuery = inputData.userMessage.toLowerCase();
const similarQuery = context.messages
  .filter(m => m.sender === 'user' && m.message_type === 'question')
  .find(m => {
    const prevQuery = m.content.toLowerCase();
    // Simple similarity check (can be enhanced with embeddings)
    const words1 = new Set(currentQuery.split(/\s+/));
    const words2 = new Set(prevQuery.split(/\s+/));
    const intersection = new Set([...words1].filter(x => words2.has(x)));
    const similarity = intersection.size / Math.max(words1.size, words2.size);
    return similarity > 0.5 && m.content !== inputData.userMessage;
  });

return {
  json: {
    context,
    similarQuery: similarQuery || null
  }
};
